UPDATE commission_rule SET scope = #{scope}, ref_id = #{refId}, staff_role = #{staffRole},
       ratio_bp = #{ratioBp}, fixed_cent = #{fixedCent}, effective_from = #{effectiveFrom},
       effective_to = #{effectiveTo}, remark = #{remark}
WHERE id = #{id}

