SELECT s.*, st.name AS staff_name
FROM commission_settle s JOIN staff st ON st.id = s.staff_id
WHERE s.id = #{id}

SELECT s.*, st.name AS staff_name FROM commission_settle s JOIN staff st ON st.id = s.staff_id
AND s.month = #{month}
ORDER BY s.month DESC, s.id DESC

